1	"use client";
2	
3	import { useState } from "react";
4	import { useRouter } from "next/navigation";
5	
6	export default function LemburThrForm({
7	  action,
8	  initialLembur,
9	  initialThr,
10	}: {
11	  action: (lemburAmount: number, thrAmount: number) => Promise<{ error: string | null }>;
12	  initialLembur: number;
13	  initialThr: number;
14	}) {
15	  const router = useRouter();
16	  const [lembur, setLembur] = useState(initialLembur > 0 ? String(initialLembur) : "");
17	  const [thr, setThr] = useState(initialThr > 0 ? String(initialThr) : "");
18	  const [error, setError] = useState<string | null>(null);
19	  const [pending, setPending] = useState(false);
20	
21	  async function handleSubmit() {
22	    setError(null);
23	    setPending(true);
24	    const result = await action(Number(lembur) || 0, Number(thr) || 0);
25	    setPending(false);
26	
27	    if (result.error) {
28	      setError(result.error);
29	      return;
30	    }
31	    router.refresh();
32	  }
33	
34	  return (
35	    <div className="space-y-2.5 rounded-xl border border-zinc-200 bg-zinc-50 p-3">
36	      <p className="text-xs font-semibold text-zinc-600">Lembur & THR</p>
37	      <div className="grid grid-cols-2 gap-2">
38	        <div>
39	          <label className="mb-1 block text-[10px] text-zinc-500">Lembur (Rp)</label>
40	          <input
41	            type="number"
42	            min="0"
43	            step="1"
44	            value={lembur}
45	            onChange={(e) => setLembur(e.target.value)}
46	            placeholder="0"
47	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
48	          />
49	        </div>
50	        <div>
51	          <label className="mb-1 block text-[10px] text-zinc-500">THR (Rp)</label>
52	          <input
53	            type="number"
54	            min="0"
55	            step="1"
56	            value={thr}
57	            onChange={(e) => setThr(e.target.value)}
58	            placeholder="0"
59	            className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
60	          />
61	        </div>
62	      </div>
63	
64	      {error && <p className="text-xs text-red-600">{error}</p>}
65	
66	      <button
67	        onClick={handleSubmit}
68	        disabled={pending}
69	        className="w-full rounded-lg bg-brand-600 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
70	      >
71	        {pending ? "Menyimpan…" : "Simpan Lembur & THR"}
72	      </button>
73	    </div>
74	  );
75	}
