1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { logActivity } from "@/lib/activity-log";
6	
7	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
8	
9	// Return value: pesan error kalau posting jurnal gagal, null kalau sukses.
10	// Baris payslips sudah kadung ditandai dibayar di titik ini (lihat pemanggil)
11	// — jadi kegagalan di sini tidak dibatalkan, hanya dilaporkan (lihat pola yang
12	// sama di finance/actions.ts postExpenseJournal, [[mini-erp-scope]]).
13	async function postPayrollJournal(
14	  supabase: SupabaseServerClient,
15	  businessId: string,
16	  date: string,
17	  description: string,
18	  amount: number,
19	): Promise<string | null> {
20	  const { error } = await supabase.rpc("post_journal_entry", {
21	    p_business_id: businessId,
22	    p_date: date,
23	    p_description: description,
24	    p_lines: [
25	      { account_code: "5-100", debit: amount, credit: 0 },
26	      { account_code: "1-001", debit: 0, credit: amount },
27	    ],
28	  });
29	  return error?.message ?? null;
30	}
