32	export type CreatePayslipResult =
33	  | { success: true; payslipId: string }
34	  | { success: false; error: string };
35	
36	export async function createPayslip(
37	  businessId: string,
38	  employeeId: string,
39	  periodStart: string,
40	  periodEnd: string,
41	): Promise<CreatePayslipResult> {
42	  if (!periodStart || !periodEnd || periodStart > periodEnd) {
43	    return { success: false, error: "Rentang tanggal tidak valid." };
44	  }
45	
46	  const supabase = await createClient();
47	
48	  const { data: employee } = await supabase
49	    .from("employees")
50	    .select("name, daily_rate")
51	    .eq("id", employeeId)
52	    .eq("business_id", businessId)
53	    .maybeSingle();
54	
55	  if (!employee) {
56	    return { success: false, error: "Karyawan tidak ditemukan." };
57	  }
58	
59	  const { data: attendanceRows } = await supabase
60	    .from("attendance")
61	    .select("status")
62	    .eq("business_id", businessId)
63	    .eq("employee_id", employeeId)
64	    .gte("date", periodStart)
65	    .lte("date", periodEnd);
66	
67	  const counts = { hadir: 0, izin: 0, sakit: 0, alpa: 0 };
68	  for (const r of attendanceRows ?? []) {
69	    counts[r.status as keyof typeof counts] += 1;
70	  }
71	
72	  const dailyRate = Number(employee.daily_rate);
73	  const basePay = dailyRate * counts.hadir;
74	
75	  const { data: payslip, error } = await supabase
76	    .from("payslips")
77	    .insert({
78	      business_id: businessId,
79	      employee_id: employeeId,
80	      period_start: periodStart,
81	      period_end: periodEnd,
82	      daily_rate: dailyRate,
83	      hadir_count: counts.hadir,
84	      izin_count: counts.izin,
85	      sakit_count: counts.sakit,
86	      alpa_count: counts.alpa,
87	      base_pay: basePay,
88	    })
89	    .select("id")
90	    .single();
91	
92	  if (error || !payslip) {
93	    return { success: false, error: error?.message ?? "Gagal membuat slip gaji." };
94	  }
95	
96	  await logActivity(
97	    supabase,
98	    businessId,
99	    "sistem",
100	    "sukses",
101	    `Slip gaji dibuat: ${employee.name}`,
102	    `${periodStart} s/d ${periodEnd} · ${counts.hadir} hari kerja`,
103	  );
104	
105	  revalidatePath(`/business/${businessId}/payroll`);
106	  return { success: true, payslipId: payslip.id };
107	}
