109	export async function deletePayslip(
110	  businessId: string,
111	  payslipId: string,
112	): Promise<{ error: string | null }> {
113	  const supabase = await createClient();
114	
115	  const { data: payslip } = await supabase
116	    .from("payslips")
117	    .select("paid_at")
118	    .eq("id", payslipId)
119	    .eq("business_id", businessId)
120	    .maybeSingle();
121	
122	  if (payslip?.paid_at) {
123	    return {
124	      error: "Slip gaji yang sudah dibayar tidak bisa dihapus (sudah ada di jurnal).",
125	    };
126	  }
127	
128	  await supabase.from("payslips").delete().eq("id", payslipId).eq("business_id", businessId);
129	  revalidatePath(`/business/${businessId}/payroll`);
130	  return { error: null };
131	}
