133	export type MarkPaidResult = { error: string | null };
134	
135	export async function markPayslipPaid(
136	  businessId: string,
137	  payslipId: string,
138	): Promise<MarkPaidResult> {
139	  const supabase = await createClient();
140	
141	  const { data: payslip } = await supabase
142	    .from("payslips")
143	    .select("id, base_pay, lembur_amount, thr_amount, paid_at, period_end, employees(name)")
144	    .eq("id", payslipId)
145	    .eq("business_id", businessId)
146	    .maybeSingle();
147	
148	  if (!payslip) {
149	    return { error: "Slip gaji tidak ditemukan." };
150	  }
151	  if (payslip.paid_at) {
152	    return { error: "Slip gaji ini sudah ditandai dibayar." };
153	  }
154	
155	  const { data: adjustments } = await supabase
156	    .from("payslip_adjustments")
157	    .select("type, amount")
158	    .eq("payslip_id", payslipId);
159	
160	  const tunjangan = (adjustments ?? [])
161	    .filter((a) => a.type === "tunjangan")
162	    .reduce((s, a) => s + Number(a.amount), 0);
163	  const potongan = (adjustments ?? [])
164	    .filter((a) => a.type === "potongan")
165	    .reduce((s, a) => s + Number(a.amount), 0);
166	  const total =
167	    Number(payslip.base_pay) +
168	    Number(payslip.lembur_amount) +
169	    Number(payslip.thr_amount) +
170	    tunjangan -
171	    potongan;
172	
173	  if (total <= 0) {
174	    return { error: "Total gaji harus lebih dari 0 untuk ditandai dibayar." };
175	  }
176	
177	  const employeeName =
178	    (payslip.employees as unknown as { name: string } | null)?.name ?? "Karyawan terhapus";
179	
180	  const { error } = await supabase
181	    .from("payslips")
182	    .update({ paid_at: new Date().toISOString() })
183	    .eq("id", payslipId);
184	
185	  if (error) {
186	    return { error: error.message };
187	  }
188	
189	  const journalError = await postPayrollJournal(
190	    supabase,
191	    businessId,
192	    payslip.period_end,
193	    `Gaji: ${employeeName}`,
194	    total,
195	  );
196	
197	  await logActivity(
198	    supabase,
199	    businessId,
200	    "sistem",
201	    journalError ? "warning" : "sukses",
202	    `Slip gaji dibayar: ${employeeName}`,
203	    journalError
204	      ? `Rp${total.toLocaleString("id-ID")} — GAGAL posting ke jurnal: ${journalError}`
205	      : `Rp${total.toLocaleString("id-ID")}`,
206	  );
207	
208	  revalidatePath(`/business/${businessId}/payroll`);
209	  revalidatePath(`/business/${businessId}/payroll/${payslipId}`);
210	
211	  return {
212	    error: journalError
213	      ? `Slip gaji ditandai dibayar, tapi gagal posting ke jurnal (${journalError}). Tambahkan jurnal koreksi manual di halaman Akuntansi → Jurnal.`
214	      : null,
215	  };
216	}
