266	export type AdjustmentType = "tunjangan" | "potongan";
267	
268	export async function addPayslipAdjustment(
269	  businessId: string,
270	  payslipId: string,
271	  type: AdjustmentType,
272	  label: string,
273	  amount: number,
274	): Promise<{ error: string | null }> {
275	  const trimmedLabel = label.trim();
276	  if (!trimmedLabel) {
277	    return { error: "Nama tunjangan/potongan wajib diisi." };
278	  }
279	  if (Number.isNaN(amount) || amount <= 0) {
280	    return { error: "Nominal harus angka lebih dari 0." };
281	  }
282	
283	  const supabase = await createClient();
284	
285	  const { data: payslip } = await supabase
286	    .from("payslips")
287	    .select("id, paid_at")
288	    .eq("id", payslipId)
289	    .eq("business_id", businessId)
290	    .maybeSingle();
291	
292	  if (!payslip) {
293	    return { error: "Slip gaji tidak ditemukan." };
294	  }
295	  if (payslip.paid_at) {
296	    return { error: "Slip gaji sudah dibayar, tidak bisa ditambah tunjangan/potongan lagi." };
297	  }
298	
299	  const { error } = await supabase.from("payslip_adjustments").insert({
300	    payslip_id: payslipId,
301	    type,
302	    label: trimmedLabel,
303	    amount,
304	  });
305	
306	  if (error) {
307	    return { error: error.message };
308	  }
309	
310	  await logActivity(
311	    supabase,
312	    businessId,
313	    "sistem",
314	    "info",
315	    `${type === "tunjangan" ? "Tunjangan" : "Potongan"} ditambahkan: ${trimmedLabel}`,
316	    `Rp${amount.toLocaleString("id-ID")}`,
317	  );
318	
319	  revalidatePath(`/business/${businessId}/payroll/${payslipId}`);
320	  return { error: null };
321	}
