3	import { useState } from "react";
4	import { useRouter } from "next/navigation";
5	import type { CreatePayslipResult } from "./actions";
6	
7	type EmployeeOption = { id: string; name: string; dailyRate: number; active: boolean };
8	
9	export default function CreatePayslipForm({
10	  businessId,
11	  employees,
12	  defaultStart,
13	  defaultEnd,
14	  action,
15	}: {
16	  businessId: string;
17	  employees: EmployeeOption[];
18	  defaultStart: string;
19	  defaultEnd: string;
20	  action: (
21	    employeeId: string,
22	    periodStart: string,
23	    periodEnd: string,
24	  ) => Promise<CreatePayslipResult>;
25	}) {
26	  const router = useRouter();
27	  const [employeeId, setEmployeeId] = useState(employees[0]?.id ?? "");
28	  const [periodStart, setPeriodStart] = useState(defaultStart);
29	  const [periodEnd, setPeriodEnd] = useState(defaultEnd);
30	  const [error, setError] = useState<string | null>(null);
31	  const [pending, setPending] = useState(false);
32	
33	  async function handleSubmit() {
34	    setError(null);
35	    if (!employeeId) {
36	      setError("Pilih karyawan dulu.");
37	      return;
38	    }
39	    setPending(true);
40	    const result = await action(employeeId, periodStart, periodEnd);
41	    setPending(false);
42	
43	    if (!result.success) {
44	      setError(result.error);
45	      return;
46	    }
47	
48	    router.push(`/business/${businessId}/payroll/${result.payslipId}`);
49	  }
50	
51	  if (employees.length === 0) {
52	    return (
53	      <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
54	        Belum ada karyawan. Tambahkan dulu di halaman Karyawan.
55	      </p>
56	    );
57	  }
58	
59	  return (
60	    <div className="space-y-3">
61	      <div>
62	        <label className="mb-1 block text-xs font-medium text-zinc-600">Karyawan</label>
63	        <select
64	          value={employeeId}
65	          onChange={(e) => setEmployeeId(e.target.value)}
66	          className="w-full rounded-xl border border-zinc-200 px-3.5 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
67	        >
68	          {employees.map((e) => (
69	            <option key={e.id} value={e.id}>
70	              {e.name}
71	              {!e.active ? " (nonaktif)" : ""} — Rp{e.dailyRate.toLocaleString("id-ID")}/hari
72	            </option>
73	          ))}
74	        </select>
75	      </div>
76	      <div className="grid grid-cols-2 gap-3">
77	        <div>
78	          <label className="mb-1 block text-xs font-medium text-zinc-600">Dari</label>
79	          <input
80	            type="date"
81	            value={periodStart}
82	            onChange={(e) => setPeriodStart(e.target.value)}
83	            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
84	          />
85	        </div>
86	        <div>
87	          <label className="mb-1 block text-xs font-medium text-zinc-600">Sampai</label>
88	          <input
89	            type="date"
90	            value={periodEnd}
91	            onChange={(e) => setPeriodEnd(e.target.value)}
92	            className="w-full rounded-xl border border-zinc-200 px-3 py-2.5 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
93	          />
94	        </div>
95	      </div>
96	
97	      {error && <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{error}</p>}
98	
99	      <button
100	        onClick={handleSubmit}
101	        disabled={pending}
102	        className="w-full rounded-xl bg-brand-600 py-2.5 text-sm font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
103	      >
104	        {pending ? "Membuat…" : "Buat Slip Gaji"}
105	      </button>
106	    </div>
107	  );
108	}
