3	import { useActionState, useRef, useEffect } from "react";
4	import type { ReconciliationState } from "./actions";
5	
6	const initialState: ReconciliationState = { error: null };
7	
8	export default function AddReconciliationForm({
9	  action,
10	  methods,
11	  today,
12	}: {
13	  action: (state: ReconciliationState, formData: FormData) => Promise<ReconciliationState>;
14	  methods: string[];
15	  today: string;
16	}) {
17	  const [state, formAction, pending] = useActionState(action, initialState);
18	  const formRef = useRef<HTMLFormElement>(null);
19	
20	  useEffect(() => {
21	    if (!pending && !state.error) {
22	      formRef.current?.reset();
23	    }
24	  }, [pending, state.error]);
25	
26	  return (
27	    <form ref={formRef} action={formAction} className="space-y-2.5">
28	      <p className="text-xs font-semibold text-zinc-600">
29	        + Catat Saldo Diterima Aktual (dari cek mutasi rekening/dashboard QRIS)
30	      </p>
31	      <div className="grid grid-cols-2 gap-2">
32	        <input
33	          name="date"
34	          type="date"
35	          defaultValue={today}
36	          required
37	          className="w-full rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
38	        />
39	        <select
40	          name="method"
41	          required
42	          className="w-full rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
43	        >
44	          {methods.map((m) => (
45	            <option key={m} value={m}>
46	              {m}
47	            </option>
48	          ))}
49	        </select>
50	        <input
51	          name="amount"
52	          type="number"
53	          min="0"
54	          step="1"
55	          placeholder="Jumlah diterima"
56	          required
57	          className="w-full rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
58	        />
59	        <input
60	          name="note"
61	          type="text"
62	          placeholder="Catatan (opsional)"
63	          className="w-full rounded-lg border border-zinc-200 px-2.5 py-2 text-xs focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
64	        />
65	      </div>
66	
67	      {state.error && (
68	        <p className="rounded-lg bg-red-50 px-3 py-2 text-xs text-red-600">{state.error}</p>
69	      )}
70	
71	      <button
72	        type="submit"
73	        disabled={pending}
74	        className="rounded-lg bg-brand-600 px-4 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
75	      >
76	        {pending ? "Menyimpan…" : "+ Catat"}
77	      </button>
78	    </form>
79	  );
80	}
