29	function formatDate(dateStr: string) {
30	  return new Date(`${dateStr}T00:00:00Z`).toLocaleDateString("id-ID", {
31	    day: "2-digit",
32	    month: "short",
33	    year: "numeric",
34	    timeZone: "UTC",
35	  });
36	}
37	
38	function toDateStr(d: Date) {
39	  return d.toISOString().slice(0, 10);
40	}
41	
42	function addDaysStr(dateStr: string, days: number) {
43	  const d = new Date(`${dateStr}T00:00:00Z`);
44	  d.setUTCDate(d.getUTCDate() + days);
45	  return toDateStr(d);
46	}
47	
48	function getPeriodStartDateStr(period: Period): string | null {
49	  const now = new Date();
50	  if (period === "today") return toDateStr(now);
51	  if (period === "week") return addDaysStr(toDateStr(now), -6);
52	  if (period === "month") return toDateStr(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)));
53	  return null;
54	}
55	
56	function getPreviousMonthLastDayStr(): string {
57	  const now = new Date();
58	  // Day 0 of the current UTC month == last day of the previous month.
59	  return toDateStr(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 0)));
60	}
