29	export default async function AttendancePage({
30	  params,
31	  searchParams,
32	}: {
33	  params: Promise<{ businessId: string }>;
34	  searchParams: Promise<{ date?: string }>;
35	}) {
36	  const { businessId } = await params;
37	  const { date: dateParam } = await searchParams;
38	  const date = dateParam && /^\d{4}-\d{2}-\d{2}$/.test(dateParam) ? dateParam : todayStr();
39	
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: employees } = await supabase
53	    .from("employees")
54	    .select("id, name")
55	    .eq("business_id", businessId)
56	    .eq("active", true)
57	    .order("created_at", { ascending: true });
58	
59	  const { data: attendanceRows } = await supabase
60	    .from("attendance")
61	    .select("employee_id, status")
62	    .eq("business_id", businessId)
63	    .eq("date", date);
64	
65	  const statusByEmployee = new Map(
66	    (attendanceRows ?? []).map((r) => [r.employee_id, r.status as AttendanceStatus]),
67	  );
68	
69	  // ── Rekap bulan berjalan (berdasarkan tanggal yang sedang dilihat) ──
70	  const monthStart = `${date.slice(0, 7)}-01`;
71	  const { data: monthRows } = await supabase
72	    .from("attendance")
73	    .select("employee_id, status")
74	    .eq("business_id", businessId)
75	    .gte("date", monthStart)
76	    .lte("date", date);
77	
78	  const recap = new Map<string, Record<AttendanceStatus, number>>();
79	  for (const e of employees ?? []) {
80	    recap.set(e.id, { hadir: 0, izin: 0, sakit: 0, alpa: 0 });
81	  }
82	  for (const r of monthRows ?? []) {
83	    const entry = recap.get(r.employee_id);
84	    if (entry) entry[r.status as AttendanceStatus] += 1;
85	  }
86	
87	  return (
88	    <div className="w-full max-w-2xl">
89	        <h1 className="text-lg font-bold text-zinc-900">Absensi — {business.name}</h1>
90	
91	        <div className="mt-4 flex items-center justify-between rounded-xl border border-zinc-200 bg-white px-3 py-2.5">
92	          <Link
93	            href={`/business/${businessId}/attendance?date=${addDaysStr(date, -1)}`}
94	            className="rounded-lg px-2 py-1 text-sm text-zinc-500 hover:bg-zinc-100"
95	          >
96	            ←
97	          </Link>
98	          <div className="text-center">
99	            <p className="text-xs font-semibold text-zinc-900">{formatDateLabel(date)}</p>
100	            {date !== todayStr() && (
