111	            className="rounded-lg px-2 py-1 text-sm text-zinc-500 hover:bg-zinc-100"
112	          >
113	            →
114	          </Link>
115	        </div>
116	
117	        <div className="mt-4 space-y-2">
118	          {employees && employees.length > 0 ? (
119	            employees.map((e) => (
120	              <AttendanceRow
121	                key={e.id}
122	                employeeName={e.name}
123	                currentStatus={statusByEmployee.get(e.id) ?? null}
124	                action={setAttendance.bind(null, businessId, e.id, date)}
125	              />
126	            ))
127	          ) : (
128	            <p className="rounded-xl border border-dashed border-zinc-200 px-4 py-6 text-center text-xs text-zinc-400">
129	              Belum ada karyawan aktif. Tambahkan dulu di halaman Karyawan.
130	            </p>
131	          )}
132	        </div>
133	
134	        {employees && employees.length > 0 && (
135	          <div className="mt-6 overflow-hidden rounded-xl bg-white shadow-sm">
136	            <div className="border-b border-zinc-100 px-4 py-3">
137	              <h2 className="text-sm font-bold text-zinc-900">Rekap Bulan Ini</h2>
138	              <p className="mt-0.5 text-[11px] text-zinc-400">
139	                {monthStart.slice(0, 7)} sampai {date}
140	              </p>
141	            </div>
142	            <div className="divide-y divide-zinc-100">
143	              {employees.map((e) => {
144	                const r = recap.get(e.id)!;
145	                return (
146	                  <div key={e.id} className="flex items-center justify-between px-4 py-2.5">
147	                    <span className="text-xs font-medium text-zinc-700">{e.name}</span>
148	                    <span className="text-[11px] text-zinc-500">
149	                      <span className="text-brand-700">{r.hadir} hadir</span> ·{" "}
150	                      <span className="text-amber-600">{r.izin} izin</span> ·{" "}
151	                      <span className="text-blue-600">{r.sakit} sakit</span> ·{" "}
152	                      <span className="text-red-600">{r.alpa} alpa</span>
153	                    </span>
154	                  </div>
155	                );
156	              })}
157	            </div>
158	          </div>
159	        )}
160	    </div>
161	  );
162	}
