160	function useActiveHref(groups: NavGroup[], pathname: string): string | null {
161	  const allHrefs = groups.flatMap((g) => g.items.map((i) => i.href));
162	  const matches = allHrefs.filter((h) => pathname === h || pathname.startsWith(`${h}/`));
163	  if (matches.length === 0) return null;
164	  return matches.sort((a, b) => b.length - a.length)[0];
165	}
166	
167	function activeGroupTitleOf(groups: NavGroup[], activeHref: string | null): string | null {
168	  if (!activeHref) return groups[0]?.title ?? null;
169	  return groups.find((g) => g.items.some((i) => i.href === activeHref))?.title ?? groups[0]?.title ?? null;
170	}
