25	const AGING_BUCKETS = ["0-30 hari", "31-60 hari", "61-90 hari", "90+ hari"] as const;
26	type AgingBucket = (typeof AGING_BUCKETS)[number];
27	
28	function agingBucketOf(dateStr: string, todayIso: string): AgingBucket {
29	  const days = Math.floor(
30	    (new Date(`${todayIso}T00:00:00Z`).getTime() - new Date(`${dateStr}T00:00:00Z`).getTime()) /
31	      86400000,
32	  );
33	  if (days <= 30) return "0-30 hari";
34	  if (days <= 60) return "31-60 hari";
35	  if (days <= 90) return "61-90 hari";
36	  return "90+ hari";
37	}
