61	
62	  if (!business) {
63	    notFound();
64	  }
65	
66	  const today = toDateStr(new Date());
67	
68	  const [{ data: customers }, { data: receivables }] = await Promise.all([
69	    supabase
70	      .from("customers")
71	      .select("id, name")
72	      .eq("business_id", businessId)
73	      .is("deleted_at", null)
74	      .order("name", { ascending: true }),
75	    supabase
76	      .from("receivables")
77	      .select("id, date, description, amount, paid_amount, customer_id")
78	      .eq("business_id", businessId)
79	      .order("date", { ascending: false })
80	      .order("created_at", { ascending: false })
81	      .limit(50),
