83	
84	  const customerMap = new Map((customers ?? []).map((c) => [c.id, c.name]));
85	
86	  const rows = (receivables ?? []) as ReceivableRow[];
87	  const totalPiutang = rows.reduce((s, r) => s + (Number(r.amount) - Number(r.paid_amount)), 0);
88	  const belumLunasCount = rows.filter((r) => Number(r.paid_amount) < Number(r.amount)).length;
89	
90	  const agingTotals = new Map<AgingBucket, number>();
91	  for (const r of rows) {
