125	          <p className="mb-1.5 text-[10.5px] font-semibold uppercase text-zinc-400">
126	            Belum Lunas
127	          </p>
128	          <p className="text-xl font-bold text-zinc-900">{belumLunasCount} tagihan</p>
129	        </div>
130	      </div>
131	
132	      {totalPiutang > 0 && (
133	        <div className="mt-3 overflow-hidden rounded-xl bg-white shadow-sm">
