145	                        ? "text-amber-600"
146	                        : i === 2
147	                          ? "text-orange-600"
148	                          : "text-red-600"
149	                  }`}
150	                >
151	                  {formatRupiah(agingTotals.get(bucket) ?? 0)}
152	                </p>
153	                <p className="mt-0.5 text-[10px] text-zinc-400">{bucket}</p>
154	              </div>
155	            ))}
156	          </div>
157	        </div>
158	      )}
