26	export default async function RekonsiliasiPage({
27	  params,
28	  searchParams,
29	}: {
30	  params: Promise<{ businessId: string }>;
31	  searchParams: Promise<{ account?: string; date?: string }>;
32	}) {
33	  const { businessId } = await params;
34	  const { account: accountParam, date } = await searchParams;
35	  const asOfDate = /^\d{4}-\d{2}-\d{2}$/.test(date ?? "")
36	    ? (date as string)
37	    : new Date().toISOString().slice(0, 10);
38	  const asOfIso = `${asOfDate}T23:59:59+07:00`;
39	
40	  const supabase = await createClient();
41	
42	  const { data: business } = await supabase
43	    .from("businesses")
44	    .select("id, name")
45	    .eq("id", businessId)
46	    .single();
47	
48	  if (!business) {
49	    notFound();
50	  }
51	
52	  const { data: accounts } = await supabase
53	    .from("accounts")
54	    .select("id, code, name, normal_balance")
55	    .eq("business_id", businessId)
56	    .eq("type", "aset")
57	    .order("code", { ascending: true });
58	
59	  if (!accounts || accounts.length === 0) {
60	    notFound();
61	  }
62	
63	  const selectedAccount =
64	    accounts.find((a) => a.id === accountParam) ?? accounts[0];
65	
66	  const { data: entries } = await supabase
67	    .from("journal_entries")
68	    .select("journal_lines(debit, credit, account_id)")
69	    .eq("business_id", businessId)
70	    .lte("date", asOfIso);
71	
72	  let raw = 0;
73	  for (const entry of entries ?? []) {
74	    const lines = entry.journal_lines as unknown as {
75	      debit: number;
76	      credit: number;
77	      account_id: string;
78	    }[];
79	    for (const l of lines) {
80	      if (l.account_id === selectedAccount.id) {
81	        raw += Number(l.debit) - Number(l.credit);
82	      }
83	    }
84	  }
85	  const bookBalance = selectedAccount.normal_balance === "debit" ? raw : -raw;
86	
87	  const { data: history } = await supabase
88	    .from("account_reconciliations")
89	    .select("id, statement_date, book_balance, statement_balance, difference, note")
