7	export default function AddAdjustmentForm({
8	  action,
9	}: {
10	  action: (type: AdjustmentType, label: string, amount: number) => Promise<{ error: string | null }>;
11	}) {
12	  const router = useRouter();
13	  const [type, setType] = useState<AdjustmentType>("tunjangan");
14	  const [label, setLabel] = useState("");
15	  const [amount, setAmount] = useState("");
16	  const [error, setError] = useState<string | null>(null);
17	  const [pending, setPending] = useState(false);
18	
19	  async function handleSubmit() {
20	    setError(null);
21	    setPending(true);
22	    const result = await action(type, label, Number(amount));
23	    setPending(false);
24	
25	    if (result.error) {
26	      setError(result.error);
27	      return;
28	    }
29	
30	    setLabel("");
31	    setAmount("");
32	    router.refresh();
33	  }
34	
35	  return (
36	    <div className="space-y-2.5 rounded-xl border border-zinc-200 bg-zinc-50 p-3">
37	      <div className="grid grid-cols-2 gap-2">
38	        <button
39	          type="button"
40	          onClick={() => setType("tunjangan")}
41	          className={`rounded-lg border-2 py-2 text-xs font-semibold transition-colors ${
42	            type === "tunjangan"
43	              ? "border-brand-500 bg-brand-50 text-brand-700"
44	              : "border-zinc-200 bg-white text-zinc-600"
45	          }`}
46	        >
47	          + Tunjangan
48	        </button>
49	        <button
50	          type="button"
51	          onClick={() => setType("potongan")}
52	          className={`rounded-lg border-2 py-2 text-xs font-semibold transition-colors ${
53	            type === "potongan"
54	              ? "border-red-400 bg-red-50 text-red-700"
55	              : "border-zinc-200 bg-white text-zinc-600"
56	          }`}
57	        >
58	          − Potongan
59	        </button>
60	      </div>
61	      <input
62	        type="text"
63	        value={label}
64	        onChange={(e) => setLabel(e.target.value)}
65	        placeholder={type === "tunjangan" ? "mis. Bonus, Uang Makan" : "mis. Kasbon, Telat"}
66	        className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
67	      />
68	      <input
69	        type="number"
70	        min="0"
71	        step="1"
72	        value={amount}
73	        onChange={(e) => setAmount(e.target.value)}
74	        placeholder="Nominal (Rp)"
75	        className="w-full rounded-lg border border-zinc-200 px-3 py-2 text-sm focus:border-brand-600 focus:outline-none focus:ring-2 focus:ring-brand-100"
76	      />
77	
78	      {error && <p className="text-xs text-red-600">{error}</p>}
79	
80	      <button
81	        onClick={handleSubmit}
82	        disabled={pending}
83	        className="w-full rounded-lg bg-brand-600 py-2 text-xs font-semibold text-white transition-colors hover:bg-brand-700 disabled:cursor-not-allowed disabled:opacity-60"
84	      >
85	        {pending ? "Menyimpan…" : "Tambah"}
86	      </button>
87	    </div>
88	  );
89	}
