23	export default async function PayslipDetailPage({
24	  params,
25	}: {
26	  params: Promise<{ businessId: string; payslipId: string }>;
27	}) {
28	  const { businessId, payslipId } = await params;
29	  const supabase = await createClient();
30	
31	  const { data: business } = await supabase
32	    .from("businesses")
33	    .select("name")
34	    .eq("id", businessId)
35	    .single();
36	
37	  const { data: payslip } = await supabase
38	    .from("payslips")
39	    .select(
40	      "id, period_start, period_end, daily_rate, hadir_count, izin_count, sakit_count, alpa_count, base_pay, lembur_amount, thr_amount, created_at, paid_at, employees(name)",
41	    )
42	    .eq("id", payslipId)
43	    .eq("business_id", businessId)
44	    .single();
45	
46	  if (!business || !payslip) {
47	    notFound();
48	  }
49	
50	  const { data: adjustments } = await supabase
51	    .from("payslip_adjustments")
52	    .select("id, type, label, amount")
53	    .eq("payslip_id", payslipId)
54	    .order("created_at", { ascending: true });
55	
56	  const employee = payslip.employees as unknown as { name: string } | null;
57	  const tunjangan = (adjustments ?? []).filter((a) => a.type === "tunjangan");
58	  const potongan = (adjustments ?? []).filter((a) => a.type === "potongan");
59	  const totalTunjangan = tunjangan.reduce((s, a) => s + Number(a.amount), 0);
60	  const totalPotongan = potongan.reduce((s, a) => s + Number(a.amount), 0);
61	  const basePay = Number(payslip.base_pay);
62	  const lemburAmount = Number(payslip.lembur_amount);
63	  const thrAmount = Number(payslip.thr_amount);
64	  const totalDiterima = basePay + lemburAmount + thrAmount + totalTunjangan - totalPotongan;
65	
66	  const boundAddAdjustment = addPayslipAdjustment.bind(null, businessId, payslipId);
67	  const boundUpdateExtras = updatePayslipExtras.bind(null, businessId, payslipId);
68	  const boundMarkPaid = markPayslipPaid.bind(null, businessId, payslipId);
69	  const isPaid = Boolean(payslip.paid_at);
70	
71	  return (
72	    <div className="w-full max-w-sm print:max-w-none">
73	        <div className="print:hidden">
74	          <PrintButton businessId={businessId} />
75	        </div>
76	
77	        <div className="mt-4 rounded-xl bg-white shadow-sm p-5 print:mt-0 print:rounded-none print:border-0 print:p-0">
78	          <div className="text-center">
79	            <p className="text-xs font-semibold uppercase text-zinc-400">{business.name}</p>
80	            <h1 className="mt-1 text-lg font-bold text-zinc-900">Slip Gaji</h1>
81	          </div>
82	
83	          <div className="mt-4 space-y-1 border-t border-dashed border-zinc-300 pt-3 text-sm">
84	            <div className="flex justify-between">
85	              <span className="text-zinc-500">Nama</span>
86	              <span className="font-medium text-zinc-900">
87	                {employee?.name ?? "Karyawan terhapus"}
88	              </span>
89	            </div>
90	            <div className="flex justify-between">
91	              <span className="text-zinc-500">Periode</span>
92	              <span className="font-medium text-zinc-900">
93	                {formatDate(payslip.period_start)} – {formatDate(payslip.period_end)}
94	              </span>
95	            </div>
96	          </div>
97	
98	          <div className="mt-3 grid grid-cols-4 gap-1.5 border-t border-dashed border-zinc-300 pt-3 text-center">
99	            <div>
100	              <p className="text-sm font-bold text-brand-700">{payslip.hadir_count}</p>
101	              <p className="text-[10px] text-zinc-400">Hadir</p>
102	            </div>
103	            <div>
104	              <p className="text-sm font-bold text-amber-600">{payslip.izin_count}</p>
105	              <p className="text-[10px] text-zinc-400">Izin</p>
106	            </div>
107	            <div>
108	              <p className="text-sm font-bold text-blue-600">{payslip.sakit_count}</p>
109	              <p className="text-[10px] text-zinc-400">Sakit</p>
110	            </div>
111	            <div>
112	              <p className="text-sm font-bold text-red-600">{payslip.alpa_count}</p>
113	              <p className="text-[10px] text-zinc-400">Alpa</p>
114	            </div>
115	          </div>
116	
117	          <div className="mt-3 space-y-1.5 border-t border-dashed border-zinc-300 pt-3 text-sm">
118	            <div className="flex justify-between">
119	              <span className="text-zinc-600">
120	                Gaji Pokok ({payslip.hadir_count} hari x {formatRupiah(Number(payslip.daily_rate))})
121	              </span>
122	              <span className="font-semibold text-zinc-900">{formatRupiah(basePay)}</span>
123	            </div>
124	            {lemburAmount > 0 && (
125	              <div className="flex justify-between text-brand-700">
126	                <span>+ Lembur</span>
127	                <span>{formatRupiah(lemburAmount)}</span>
